declare namespace SigApi {
    interface CompositeControl {
        /**
         * Returns the name
         * 
         * @returns {string}
         */
        getName(): string
        /**
         * Sets the name
         * 
         * @param {string} name
         */
        setName(name: string): void
        /**
         * Returns the controlsJson
         * 
         * @returns {object}
         */
        getControlsJson(): any
    }
}
